Inorder Traversal is a method to traverse a tree such that for each node, you first traverse its left subtree, then visit the node itself, and finally traverse its right subtree.Examples:Input:      Output: [2, 1, 3]Explanation: The Inorder Traversal visits the nodes in the following order: Left, Root, Right. Therefore, we visit the left node 2, then the root node 1 and lastly the right node 3.Input : Output: [4, 2, 5, 1, 3, 6]Explanation: Inorder Traversal (Left -> Root -> Right). Visit 4 -> 2 -> 5 -> 1 -> 3 -> 6, resulting in 4 2 5 1 3 6.     Try It YourselfHow does Inorder Traversal work?[Approach] Using RecursionThe main idea is to traverse the tree recursively, starting from the root node, first completely traverse the left subtree, then visit the root node itself, and finally completely traverse the right subtree.
            C++

    #include<iostream>
#include <vector>
using namespace std;

//Node Structure
class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int x) {
        data = x;
        left = right = NULL;
    }
};

void inOrder(Node* node, vector<int>& res) {
    if (node == nullptr)
        return;

    // Traverse the left subtree first
    inOrder(node->left, res);

    // Visit the current node
    res.push_back(node->data);

    // Traverse the right subtree last
    inOrder(node->right, res);
}

int main() {
    // Create binary tree
    //       1
    //      /  \
    //    2     3
    //   / \     \
    //  4   5     6
    Node* root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);
    root->left->left = new Node(4);
    root->left->right = new Node(5);
    root->right->right = new Node(6);

    vector<int> res;
    inOrder(root, res);

    for( int node : res) 
        cout << node << " ";

    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>

//Node Structure
struct Node {
    int data;
    struct Node* left;
    struct Node* right;
};

// Function to create a new node
struct Node* newNode(int x) {
    struct Node* node = (struct Node*)malloc(sizeof(struct Node));
    node->data = x;
    node->left = NULL;
    node->right = NULL;
    return node;
}

void inOrder(struct Node* node) {
    if (node == NULL)
        return;

    // Traverse the left subtree first
    inOrder(node->left);

    // Visit the current node
    printf("%d ", node->data);

    // Traverse the right subtree last
    inOrder(node->right);
}

int main() {
    // Create binary tree
    //       1
    //      /  \
    //    2     3
    //   / \     \
    //  4   5     6
    struct Node* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->left->right = newNode(5);
    root->right->right = newNode(6);

    inOrder(root);
    printf("\n");

    return 0;
}


